WITH deals AS (SELECT d.id order_id, DATE(d.Deal_Time,'Europe/Kyiv') order_date, d.Deal_Time order_ts, d.Stage stage, d.Payment_Scheme ps, d.Billed_Amount billed, d.Phone phone FROM `perla-holistic-com.crm_data.zoho_deals` d WHERE d.Region='UA' AND NOT IFNULL(d.deleted,FALSE) AND d.Channel='Fast Order' AND DATE(d.Deal_Time,'Europe/Kyiv') BETWEEN '2026-01-01' AND '2026-09-30'),
calls AS (SELECT REGEXP_REPLACE(customer_number, r'\D','') pd, call_date_time_utc, bill_sec FROM `perla-holistic-com.analytics.calls` WHERE DATE(call_date_time_kyiv) BETWEEN '2026-01-01' AND '2026-10-02' AND call_type='outgoing'),
cc AS (SELECT d.order_id, MIN(c.call_date_time_utc) first_call, COUNTIF(c.bill_sec>0) answered, COUNT(*) attempts FROM deals d JOIN calls c ON RIGHT(c.pd,9)=RIGHT(REGEXP_REPLACE(IFNULL(d.phone,''), r'\D',''),9) AND c.call_date_time_utc >= d.order_ts AND c.call_date_time_utc < TIMESTAMP_ADD(d.order_ts, INTERVAL 48 HOUR) GROUP BY 1),
paid AS (SELECT id order_id, order_num FROM `perla-holistic-com.analytics.orders` WHERE market='UA')
SELECT FORMAT_DATE('%Y-%m', order_date) month, COUNT(*) requests, COUNTIF(stage IN ('Successful','Successful/Deferred Shipment')) successful, COUNTIF(stage IN ('Delivery','Deferred Shipment','Out for Delivery')) in_progress, COUNTIF(stage='Canceled') canceled, COUNTIF(stage='Terminated') refused,
  COUNTIF(ps='Cash On Delivery') cod, COUNTIF(cc.attempts>0) called, COUNTIF(cc.answered>0) reached, APPROX_QUANTILES(TIMESTAMP_DIFF(cc.first_call, d.order_ts, MINUTE), 2)[OFFSET(1)] median_min_to_call, COUNTIF(p.order_num=1) new_customers, ROUND(SUM(IF(stage IN ('Successful','Successful/Deferred Shipment'), billed, 0))) billed_successful
FROM deals d LEFT JOIN cc USING(order_id) LEFT JOIN paid p USING(order_id) GROUP BY 1 ORDER BY 1
